\mathsf{Ctx}_{\lambda\Pi R}
=
\{\langle x_i:A_i\rangle_{i<n}:n\in\mathbb N,\ x_i\in\mathsf{Var}_{\lambda\Pi R},\ A_i\in\mathsf{Exp}_{\lambda\Pi R},\ i\ne j\Rightarrow x_i\ne x_j\},

\mathsf{Sig}_{\lambda\Pi R}
=
\{\langle c_i:A_i\rangle_{i<n}:n\in\mathbb N,\ c_i\in\mathsf{Const}_{\lambda\Pi R},\ A_i\in\mathsf{Exp}_{\lambda\Pi R},\ i\ne j\Rightarrow c_i\ne c_j\}.

\mathsf{ConvSeq}_{\lambda\Pi R}
=
\{\rho:n\to\mathsf{Exp}_{\lambda\Pi R}:n\in\mathbb N,\ n>0,\ \forall i+1<n\ ((\rho_i,\rho_{i+1})\in\mathsf{ConvStep}_{\lambda\Pi R})\}.

\mathsf{Rule}_{app}^{\lambda\Pi R}
=
\{(\langle\Gamma\vdash M:\Pi x:A.B,\Gamma\vdash N:A\rangle,\Gamma\vdash MN:\operatorname{Sub}_{\lambda\Pi R}(B,x,N))\},

\mathsf{TreeDom}_{\lambda\Pi R}
=
\{D\subseteq\mathbb N^{<\omega}:D\ne\varnothing,\ D\text{ 有限且前缀封闭},\ \forall p\in D\ \exists k\in\mathbb N\ \{i:p^\frown\langle i\rangle\in D\}=\{0,\ldots,k-1\}\}.

\mathsf{Delta}_{\lambda\Pi R}
=
(\mathsf{Const}_{\lambda\Pi R},\operatorname{ctype}_{\lambda\Pi R},R,\mathsf{Env}_{\lambda\Pi R},\operatorname{Act}_{\lambda\Pi R},\mathsf{RewriteRuleOK}_{\lambda\Pi R},\mathsf{RewriteCert}_{\lambda\Pi R},\operatorname{src}_{R},\operatorname{tgt}_{R},\mathsf{ConvStep}_{\lambda\Pi R},\mathsf{ConvSeq}_{\lambda\Pi R},\mathsf{NoConfluenceClaim}_{\lambda\Pi R},\to^0_R,\to_R,\equiv_{\beta R},\mathsf{RSeq}_{\lambda\Pi R}).
